import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    a = list(map(int, data[1:1+n]))

    # Sort the array
    a.sort()

    # Check consecutive triplets
    for i in range(n - 2):
        if a[i] + a[i+1] > a[i+2]:
            print("YES")
            return

    print("NO")

if __name__ == "__main__":
    solve()
"}

