def is_centrosymmetric(points, n):
    # Find the longest diagonal
    max_dist2 = 0
    center_idx = 0
    for i in range(n):
        for j in range(i+1, n):
            dx = points[i][0] - points[j][0]
            dy = points[i][1] - points[j][1]
            dist2 = dx*dx + dy*dy
            if dist2 > max_dist2:
                max_dist2 = dist2
                center_idx = (i + j) // 2  # Midpoint of longest diagonal

    # Check if all points are symmetric about center
    center = points[center_idx]
    for i in range(n):
        # Find diametrically opposite point
        found = False
        for j in range(n):
            if i != j:
                # Check if points[i] and points[j] are symmetric about center
                dx = points[i][0] - center[0]
                dy = points[i][1] - center[1]
                if points[j][0] == center[0] - dx and points[j][1] == center[1] - dy:
                    found = True
                    break
        if not found:
            return False
    return True

n = int(input())
points = []
for _ in range(n):
    x, y = map(int, input().split())
    points.append((x, y))

if is_centrosymmetric(points, n):
    print("YES")
else:
    print("NO")
"}

