def is_centrosymmetric(points, n):
    # Try all possible centers (midpoints of pairs)
    for i in range(n):
        for j in range(i+1, n):
            # Check if this pair defines a symmetry
            mid_x = (points[i][0] + points[j][0]) / 2
            mid_y = (points[i][1] + points[j][1]) / 2

            # Check if all points are symmetric about this midpoint
            all_symmetric = True
            for k in range(n):
                # Check if points[k] has a symmetric counterpart
                found = False
                for l in range(n):
                    if k == l:
                        continue

                    dx_k = points[k][0] - mid_x
                    dy_k = points[k][1] - mid_y

                    dx_l = points[l][0] - mid_x
                    dy_l = points[l][1] - mid_y

                    if dx_k == -dx_l and dy_k == -dy_l:
                        found = True
                        break

                if not found:
                    all_symmetric = False
                    break

            if all_symmetric:
                return True

    return False

