n, m, k = map(int, input().split())
matrix = []
for _ in range(n):
    row = input().strip()
    matrix.append(list(row))

def count_ways(matrix, n, m, k, is_row=True):
    """
    Count ways to find k consecutive empty seats in rows or columns
    """
    count = 0

    if is_row:
        # Scan rows
        for i in range(n):
            for j in range(m - k + 1):
                # Check if positions i, j to i, j+k-1 are all '.'
                valid = True
                for offset in range(k):
                    if matrix[i][j + offset] != '.':
                        valid = False
                        break
                if valid:
                    count += 1
    else:
        # Scan columns
        for j in range(m):
            for i in range(n - k + 1):
                # Check if positions i, j to i+k-1, j are all '.'
                valid = True
                for offset in range(k):
                    if matrix[i + offset][j] != '.':
                        valid = False
                        break
                if valid:
                    count += 1

    return count

def main():
    ways = 0

    # Count ways in rows
    ways += count_ways(matrix, n, m, k, is_row=True)

    # Count ways in columns
    ways += count_ways(matrix, n, m, k, is_row=False)

    print(ways)

if __name__ == "__main__":
    main()
"}

