def is_convex(grid):
    n = len(grid)
    m = len(grid[0])

    # Find all black cells
    black_cells = []
    for i in range(n):
        for j in range(m):
            if grid[i][j] == 'B':
                black_cells.append((i, j))

    if not black_cells:
        return False  # Shouldn't happen per problem statement

    # Find the bounding rectangle
    min_row = min(i for i, j in black_cells)
    max_row = max(i for i, j in black_cells)
    min_col = min(j for i, j in black_cells)
    max_col = max(j for i, j in black_cells)

    # Check if all cells in this rectangle are black
    for i in range(min_row, max_row + 1):
        for j in range(min_col, max_col + 1):
            if grid[i][j] != 'B':
                return False

    return True

n, m = map(int, input().split())
grid = []
for _ in range(n):
    line = input().strip()
    grid.append(line)

if is_convex(grid):
    print("YES")
else:
    print("NO")
