def solve():
    t = int(input())
    for _ in range(t):
        n, m = map(int, input().split())
        # Compute XOR of Grundy numbers for all cells
        xor_sum = 0
        for i in range(n):
            for j in range(m):
                # Use (n-i) XOR (m-j) as the Grundy number for cell (i, j)
                xor_sum ^= (n - i) ^ (m - j)
        # If XOR sum is non-zero, Ashish wins; otherwise, Jeel wins
        if xor_sum != 0:
            print("Ashish")
        else:
            print("Jeel")

solve()
