    for _ in range(t):
        n, m = map(int, input().split())
        xor_sum = 0
        for i in range(n):
            row = list(map(int, input().split()))
            for j in range(m):
                val = row[j]
                # Grundy number = value XOR (i XOR j)
                xor_sum ^= val ^ (i ^ j)
        if xor_sum != 0:
            print("Ashish")
        else:
            print("Jeel")

