A, B, C = map(int, input().split())

if A == 0:
    if B == 0:
        if C == 0:
            print(-1)
        else:
            print(0)
    else:
        # linear: Bx + C = 0 => x = -C/B
        x = -C / B
        print(1)
        print(f"{x:.6f}")
else:
    D = B*B - 4*A*C
    if D < 0:
        print(0)
    elif D == 0:
        x = -B / (2 * A)
        print(1)
        print(f"{x:.6f}")
    else:
        sqrt_D = D**0.5
        x1 = (-B - sqrt_D) / (2 * A)
        x2 = (-B + sqrt_D) / (2 * A)
        if x1 > x2:
            x1, x2 = x2, x1
        print(2)
        print(f"{x1:.6f}")
        print(f"{x2:.6f}")
"}

