import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    n = int(data[0])
    coords = list(map(int, data[1:1+n]))
    coords.sort()

    # Check for self-intersections
    intersect = False
    for i in range(n - 1):
        for j in range(i + 1, n):
            # Check if intervals (coords[i], coords[j]) and (coords[k], coords[l]) intersect
            for k in range(i + 1, n):
                for l in range(k + 1, n):
                    # Check if intervals overlap but are not nested
                    a, b = coords[i], coords[j]
                    c, d = coords[k], coords[l]

                    # Check if intervals (a, b) and (c, d) intersect
                    if (a < c < b < d) or (c < a < d < b):
                        intersect = True
                        break
                if intersect:
                    break
            if intersect:
                break
        if intersect:
            break

    print("yes" if intersect else "no")

if __name__ == "__main__":
    solve()
"}

