def count_squares(n, m):
    """Count the number of distinct squares in an n x m table"""
    a = min(n, m)
    b = max(n, m)
    total = 0

    for k in range(1, a + 1):
        total += (n - k + 1) * (m - k + 1)

    return total

x = int(input())
results = []

# Try all possible (n, m) pairs where n <= m <= some upper bound
# We'll use an upper bound based on the fact that the number of squares grows quadratically
# For x <= 10^18, we can use an upper bound like 10^6 or 10^9
for n in range(1, int((2 * x) ** 0.5) + 2):
    for m in range(n, int((2 * x) ** 0.5) + 2):
        if count_squares(n, m) == x:
            results.append((n, m))

# Also check cases where m > sqrt(2x)
for n in range(1, int((2 * x) ** 0.5) + 2):
    for m in range(int((2 * x) ** 0.5) + 2, 2 * x):
        if count_squares(n, m) == x:
            results.append((n, m))

# Also check cases where n > sqrt(2x)
for m in range(1, int((2 * x) ** 0.5) + 2):
    for n in range(int((2 * x) ** 0.5) + 2, 2 * x):
        if count_squares(n, m) == x:
            results.append((n, m))

# Sort the results
results.sort()

print(len(results))
for n, m in results:
    print(n, m)
