def solve():
    N, K = map(int, input().split())
    M_list = list(map(int, input().split()))

    center = (K + 1) // 2

    # Track which seats are taken
    taken = [[False] * K for _ in range(K)]

    for M in M_list:
        found = False

        # Try each row
        for row in range(1, K + 1):
            # Try to find M consecutive seats in this row
            for start in range(1, K - M + 2):
                # Check if all seats from start to start+M-1 are available
                all_available = True
                for col in range(start, start + M):
                    if taken[row - 1][col - 1]:
                        all_available = False
                        break

                if all_available:
                    # Calculate remoteness for each seat
                    distances = []
                    for col in range(start, start + M):
                        dist = abs(row - center) + abs(col - center)
                        distances.append(dist)

                    # Total remoteness is the sum of distances
                    total_dist = sum(distances)

                    # We found a valid option, record it
                    found = True
                    best = (row, start, start + M - 1, total_dist)
                    break

            if found:
                break

        if found:
            print(f"{best[0]} {best[1]} {best[2]}")
            # Mark these seats as taken
            for col in range(best[1], best[2] + 1):
                taken[best[0] - 1][col - 1] = True
        else:
            print(-1)

solve()
