def find_suffixes(s):
    n = len(s)
    result = set()

    # Try each possible root length
    for root_length in range(5, n):
        # The suffix part starts at position root_length
        suffix_start = root_length
        suffix_part = s[root_length:]

        # Try to split this suffix part
        # Use dynamic programming to find all valid suffixes
        # dp[i] = set of suffixes that can form the substring ending at i
        dp = [set() for _ in range(len(suffix_part) + 1)]
        dp[0].add("")

        for i in range(len(suffix_part) + 1):
            for suffix in dp[i]:
                # Try adding a suffix of length 2
                if i + 2 <= len(suffix_part):
                    dp[i+2].add(suffix + suffix_part[i:i+2])
                # Try adding a suffix of length 3
                if i + 3 <= len(suffix_part):
                    dp[i+3].add(suffix + suffix_part[i:i+3])

        # Collect all suffixes from the valid splits
        # But we need to extract individual suffixes, not the concatenation
        # So we need to trace back

        # For the final suffix
        final_suffixes = set()
        for suffix in dp[len(suffix_part)]:
            if len(suffix) > 0:
                final_suffixes.add(suffix)

        # Add all suffixes from the splits
        for i in range(len(suffix_part) + 1):
            for suffix in dp[i]:
                if len(suffix) > 0:
                    result.add(suffix)

    return sorted(result)

