    result = set()

    # Try each possible root length
    for root_length in range(5, n):
        # The suffix part starts at position root_length
        suffix_start = root_length
        suffix_part = s[root_length:]

        # Check if we can split this suffix part into suffixes
        # Try different splits recursively

        # A simple recursive approach
        def can_split(i, last_suffix):
            if i == len(suffix_part):
                return True

            if i + 2 <= len(suffix_part) and suffix_part[i:i+2] != last_suffix:
                if can_split(i+2, suffix_part[i:i+2]):
                    result.add(suffix_part[i:i+2])
