def solve():
    import sys
    data = sys.stdin.read().strip().split()
    if not data:
        return

    it = iter(data)
    n = int(next(it))
    k = int(next(it))

    # Build graph: edges between snacks
    # If guest A covers both snacks of guest B, we need to avoid A before B
    # So we add an edge from guest A to guest B

    # For each guest, store their set of favorite snacks
    guest_to_flavors = []
    for _ in range(k):
        x = int(next(it))
        y = int(next(it))
        guest_to_flavors.append(set([x, y]))

    # Build dependencies: if guest i covers both snacks of guest j, add edge i -> j
    edges = set()
    for i in range(k):
        for j in range(k):
            if i == j:
                continue
            if guest_to_flavors[i].issuperset(guest_to_flavors[j]):
                edges.add((i, j))

    # Build adjacency list for topological sort (only for guests)
    adj = {i: [] for i in range(k)}
    in_degree = {i: 0 for i in range(k)}

    for u, v in edges:
        adj[u].append(v)
        in_degree[v] += 1

    # Kahn's algorithm for topological sort
    queue = [i for i in range(k) if in_degree[i] == 0]

    result = []

    while queue:
        u = queue.pop(0)
        result.append(u)
        for v in adj[u]:
            in_degree[v] -= 1
            if in_degree[v] == 0:
                queue.append(v)

    # The number of sad guests is k - len(result)
    print(k - len(result))

solve()
