import sys

def is_in_set(n, a, b):
    """Check if n is in the set generated by 1, x*a, x+b"""
    if n == 1:
        return True

    # BFS: we can multiply by a or add b
    # Work backwards from n to 1
    queue = deque([n])
    visited = set([n])

    while queue:
        curr = queue.popleft()

        # If we reach 1, we're done
        if curr == 1:
            return True

        # Try dividing by a (reverse of multiply by a)
        if curr % a == 0:
