                best_x = x
                best_yl = yl
                best_yr = yr

                # If there's a tie, choose the row with smaller x
                # If still tie, choose the segment with smaller yl
                for x2 in range(x + 1, K + 1):
                    for yl2 in range(1, K - m + 2):
                        yr2 = yl2 + m - 1
                        total2 = 0
                        for y2 in range(yl2, yr2 + 1):
