import sys

def is_spruce(matrix, n, m, x, y, k):
    """Check if there's a spruce of height k with origin at (x, y)"""
    for i in range(x, x + k):
        # Row i
        start_col = y - i + x + 1
        end_col = y + i - x - 1

        # Check if start_col <= end_col
        if start_col > end_col:
            return False

        # Check if we're out of bounds
        if start_col < 0 or end_col >= m or i >= n:
            return False

        # Check all cells in this row between start_col and end_col
        for col in range(start_col, end_col + 1):
            if matrix[i][col] != '*':
                return False

    return True

def solve() -> None:
    data = sys.stdin.read().strip().split()
    if not data:
        return

    it = iter(data)
    t = int(next(it))

    for _ in range(t):
        n = int(next(it))
        m = int(next(it))
        matrix = []
        for _ in range(n):
            row = ''.join(['.' for _ in range(m)])
            row = ''.join(next(it) for _ in range(m))
            matrix.append(row)

        count = 0
        for x in range(n):
            for y in range(m):
                # Try all possible heights from 1 to maximum possible
                max_k = min(n - x, m)
                for k in range(1, max_k + 1):
                    if is_spruce(matrix, n, m, x, y, k):
                        count += 1

        print(count)

if __name__ == "__main__":
    solve()
"}

