import sys

def solve(text):
    words = text.split()
    word_set = set(words)
    word_map = {}

    # For each word, record its prefixes
    for word in words:
        prefix_map = {}
        for i in range(len(word)):
            prefix = word[:i+1]
            prefix_map[prefix] = word
        word_map[word] = prefix_map

    # Process the text
    chars = list(text)
    n = len(chars)

    # dp[i] = minimum clicks to reach position i
    dp = [0] * (n + 1)

    for i in range(n):
        # Option 1: type the character
        dp[i+1] = dp[i] + 1

        # Option 2: autocomplete if possible
        prefix = chars[i]
        for word in words:
            if word.startswith(prefix):
                if len(prefix) < len(word):
                    # Can autocomplete
                    dp[i+1] = min(dp[i+1], dp[i] + 1)
                break

    return dp[n]

if __name__ == "__main__":
    text = sys.stdin.read().strip()
    print(solve(text))
"}

