def can_break_half(a, b):
    """Check if we can break the bar in half."""
    return a % 2 == 0 or b % 2 == 0


def can_chip_third(a, b):
    """Check if we can chip off a third of the bar."""
    return a % 3 == 0 or b % 3 == 0


def break_half(a, b, dim):
    """Break the bar in half along the specified dimension (0 for vertical, 1 for horizontal)."""
    if dim == 0:
        return (a // 2, b), (a // 2, b)
    else:
        return (a, b // 2), (a, b // 2)


def chip_third(a, b, dim):
    """Chip off a third of the bar along the specified dimension (0 for vertical, 1 for horizontal)."""
    if dim == 0:
        return (a // 3 * 2, b), (a // 3 * 2, b)
    else:
        return (a, b // 3 * 2), (a, b // 3 * 2)


def solve(a1, b1, a2, b2):
    """Find the minimum number of operations to make both bars have the same area."""
    from collections import deque

    # Initial areas
    area1 = a1 * b1
    area2 = a2 * b2

    # BFS: (area1, area2, ops)
    queue = deque([(area1, area2, 0)])
    visited = set()
    visited.add((area1, area2))

    while queue:
        area1, area2, ops = queue.popleft()

        # Check if we've reached the target
        if area1 == area2:
            return ops, (a1, b1), (a2, b2)

        # Try breaking bar 1 in half
        if area1 % 2 == 0:
            new_area1 = area1 // 2
            if new_area1 not in visited:
                visited.add(new_area1)
                queue.append((new_area1, area2, ops + 1))

        # Try breaking bar 2 in half
        if area2 % 2 == 0:
            new_area2 = area2 // 2
            if new_area2 not in visited:
                visited.add(new_area2)
                queue.append((area1, new_area2, ops + 1))

        # Try chipping off a third from bar 1
        if area1 % 3 == 0:
            new_area1 = area1 * 2 // 3
            if new_area1 not in visited:
                visited.add(new_area1)
                queue.append((new_area1, area2, ops + 1))

        # Try chipping off a third from bar 2
        if area2 % 3 == 0:
            new_area2 = area2 * 2 // 3
            if new_area2 not in visited:
                visited.add(new_area2)
                queue.append((area1, new_area2, ops + 1))

    return -1, None, None


def main():
    a1, b1 = map(int, input().split())
    a2, b2 = map(int, input().split())

    ops, result1, result2 = solve(a1, b1, a2, b2)

    if ops == -1:
        print(-1)
    else:
        print(ops)
        print(result1[0], result1[1])
        print(result2[0], result2[1])

if __name__ == "__main__":
    main()
