import sys

def determine_category(percentile):
    """Determine category based on percentile"""
    if percentile > 50:
        return "noob"
    elif 20 < percentile <= 50:
        return "random"
    elif 10 < percentile <= 20:
        return "average"
    elif 1 < percentile <= 10:
        return "hardcore"
    else:
        return "pro"


def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    players = {}

    idx = 1
    for _ in range(n):
        name = data[idx]
        points = int(data[idx + 1])
        idx += 2

        if name not in players:
            players[name] = points
        else:
            players[name] = max(players[name], points)

    # Calculate percentiles
    results = sorted(players.values())
    m = len(players)

    print(m)

    for name, best in players.items():
        # Count players with strictly better results
        better = sum(1 for score in results if score > best)

        percentile = (better / m) * 100
        category = determine_category(percentile)
        print(f"{name} {category}")

if __name__ == "__main__":
    main()
"}

