from collections import defaultdict

def convex_hull(points):
    """Compute convex hull of a set of points using Andrew's monotone chain algorithm"""
    points = sorted(set(points))
    if len(points) <= 1:
        return points
    lower = []
    for p in points:
        while len(lower) >= 2 and cross(lower[-2], lower[-1], p) <= 0:
            lower.pop()
        lower.append(p)
    upper = []
    for p in reversed(points):
        while len(upper) >= 2 and cross(upper[-2], upper[-1], p) <= 0:
            upper.pop()
        upper.append(p)
    return lower[:-1] + upper[:-1]

def cross(o, a, b):
    """Cross product of OA and OB"""
    return (a[0] - o[0]) * (b[1] - o[1]) - (a[1] - o[1]) * (b[0] - o[0])

def is_congruent_triangle(a, b):
    """Check if two triangles (sorted by angle) are congruent"""
    def triangle_key(triangle):
        # Sort by angle from the centroid
        cx = sum(p[0] for p in triangle) / len(triangle)
        cy = sum(p[1] for p in triangle) / len(triangle)
        # Sort by angle
        angles = []
        for p in triangle:
            dx = p[0] - cx
            dy = p[1] - cy
            angles.append((dx, dy))
        angles.sort()
        return tuple(angles)

    # Sort each triangle by angle
    key_a = triangle_key(a)
    key_b = triangle_key(b)
    return key_a == key_b

