def solve():
    import sys
    input = sys.stdin.read().split()
    data = iter(input)

    t = int(next(data))

    for _ in range(t):
        n = int(next(data))
        q = int(next(data))

        a = [int(next(data)) for _ in range(n)]

        # Maintain an array of the n largest elements
        # We'll use a Fenwick Tree to find the k-th largest element
        max_val = n

        # Fenwick Tree implementation
        class FenwickTree:
            def __init__(self, max_val):
                self.max_val = max_val
                self.tree = [0] * (max_val + 2)

            def update(self, idx, delta):
                while idx <= self.max_val:
                    self.tree[idx] += delta
                    idx += idx & -idx

            def query(self, idx):
                res = 0
                while idx > 0:
                    res += self.tree[idx]
                    idx -= idx & -idx
                return res

        ft = FenwickTree(n)
        for val in a:
            ft.update(val, 1)

        def find_kth(k):
            low = 1
            high = n
            while low < high:
                mid = (low + high) // 2
                count = ft.query(n) - ft.query(mid - 1)
                if count >= k:
                    high = mid
                else:
                    low = mid + 1
            return low

        def compute_max_strength():
            max_strength = 0
            # Try all possible subsequences lengths
            for k in range(1, n + 1):
                elements = []
                for i in range(k):
                    elements.append(find_kth(i + 1))
                elements.sort(reverse=True)

                strength = 0
                for i, val in enumerate(elements):
                    if i % 2 == 0:
                        strength += val
                    else:
                        strength -= val
                max_strength = max(max_strength, strength)
            return max_strength

        print(compute_max_strength())

        # Process swaps
        for __ in range(q):
            l = int(next(data))
            r = int(next(data))

            a[l-1], a[r-1] = a[r-1], a[l-1]

            ft.update(a[l-1], 1)
            ft.update(a[r-1], -1)

            print(compute_max_strength())

