from collections import deque

def bfs(grid, r, c, start_r, start_c):
    """
    BFS from (start_r, start_c) to determine minimum distances to all cells.
    """
    rows, cols = len(grid), len(grid[0])
    dist = [[-1] * cols for _ in range(rows)]
    q = deque([(start_r, start_c)])
    dist[start_r][start_c] = 0

    while q:
        x, y = q.popleft()
        for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nx, ny = x + dx, y + dy
            if 0 <= nx < rows and 0 <= ny < cols and grid[nx][ny] != 'T' and dist[nx][ny] == -1:
                dist[nx][ny] = dist[x][y] + 1
                q.append((nx, ny))

    return dist

def solve():
    r, c = map(int, input().split())
    grid = []
    start_r, start_c = -1, -1
    exit_r, exit_c = -1, -1

    for i in range(r):
        row = list(input().strip())
        for j in range(c):
            if row[j] == 'S':
                start_r, start_c = i, j
            elif row[j] == 'E':
                exit_r, exit_c = i, j
        grid.append(row)

    # BFS from start and exit
    dist_start = bfs(grid, r, c, start_r, start_c)
    dist_exit = bfs(grid, r, c, exit_r, exit_c)

    # Count breeders that can battle
    battles = 0
    # Check if start and exit are reachable (should always be true)
    if dist_start[exit_r][exit_c] != -1:
        for i in range(r):
            for j in range(c):
