from collections import deque

def solve():
    r, c = map(int, input().split())
    grid = []
    start = None
    exit_pos = None

    for i in range(r):
        row = input().strip()
        grid.append(row)

        for j, ch in enumerate(row):
            if ch == 'S':
                start = (i, j)
            elif ch == 'E':
                exit_pos = (i, j)

    # BFS to find shortest distance from start to exit
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
    visited = [[False] * c for _ in range(r)]
    queue = deque([(start[0], start[1], 0)])  # (row, col, distance)
    visited[start[0]][start[1]] = True

    d = 0
    while queue:
        row, col, dist = queue.popleft()

        if (row, col) == exit_pos:
            d = dist
            break

        for dr, dc in directions:
            nr, nc = row + dr, col + dc
            if 0 <= nr < r and 0 <= nc < c and not visited[nr][nc]:
                if grid[nr][nc] != 'T':
                    visited[nr][nc] = True
                    queue.append((nr, nc, dist + 1))

    # BFS to find shortest distances from each cell to exit
    visited = [[False] * c for _ in range(r)]
    distances = [[-1] * c for _ in range(r)]
    queue = deque([exit_pos])
    visited[exit_pos[0]][exit_pos[1]] = True
    distances[exit_pos[0]][exit_pos[1]] = 0

    while queue:
        row, col = queue.popleft()

        for dr, dc in directions:
            nr, nc = row + dr, col + dc
            if 0 <= nr < r and 0 <= nc < c and not visited[nr][nc]:
                if grid[nr][nc] != 'T':
                    visited[nr][nc] = True
                    distances[nr][nc] = distances[row][col] + 1
                    queue.append((nr, nc))

    # Calculate total breeders that can intercept us at the exit
    total_breeders = 0
    for i in range(r):
        for j in range(c):
            if (i, j) != exit_pos and distances[i][j] != -1 and (distances[i][j] < d or distances[i][j] == d):
                if '0' <= grid[i][j] <= '9':
                    total_breeders += int(grid[i][j])

