    points_engine2 = [(data[2 + n*2 + i*2], data[3 + n*2 + i*2]) for i in range(m)]

    all_points = points_engine1 + points_engine2

    hull = convex_hull(all_points)

    # Check if all points are on the convex hull
    all_on_hull = all(p in hull for p in all_points)

    print("YES" if all_on_hull else "NO")

if __name__ == "__main__":
