    """Calculate minimum moves to transform A to B"""
    n = len(A)

    # Create a dictionary to count positions for each character
    char_positions = {}
    for i in range(n):
        if A[i] not in char_positions:
            char_positions[A[i]] = []
        char_positions[A[i]].append(i)

