def solve():
    text = input().strip()
    words = text.split()

    # Dictionary to store all words
    all_words = words

    # Dictionary to store prefixes and their counts
    prefix_counts = {}

    # List to store the answer
    answer = []

    for word in words:
        # For each prefix of the word, check if there's a unique match
        unique_prefix = None
        for i in range(1, len(word) + 1):
            prefix = word[:i]

            # Count how many words have this prefix
            count = 0
            for other in all_words:
                if other.startswith(prefix):
                    count += 1

            if count == 1:
                unique_prefix = prefix
                break

        if unique_prefix:
            # Autocomplete after typing the unique prefix
            answer.append(len(unique_prefix))
        else:
            # Type the entire word
            answer.append(len(word))

    print(sum(answer))

solve()
