import math
from itertools import combinations

def distance(p1, p2):
    return math.sqrt((p1[0] - p2[0])**2 + (p1[1] - p2[1])**2)

def is_square(points):
    dists = []
    for i in range(len(points)):
        for j in range(i+1, len(points)):
            dists.append(distance(points[i], points[j]))

    dists.sort()

    # For a square, we should have 2 distinct distances: side length and diagonal
    # The 4 smallest distances should be equal (sides)
    # The 2 largest distances should be equal (diagonals)
    # The diagonals should be sqrt(2) times the side length

    if len(set(dists[:4])) != 1 or len(set(dists[4:])) != 1:
        return False

    side = dists[0]
    diagonal = dists[4]

    return abs(diagonal - side * math.sqrt(2)) < 1e-9

def is_rectangle(points):
    dists = []
    for i in range(len(points)):
        for j in range(i+1, len(points)):
            dists.append(distance(points[i], points[j]))

    dists.sort()

    # For a rectangle, we should have 3 distinct distances
    # The 2 largest distances should be equal (diagonals)
    # The remaining 4 distances should be: 2 of length a and 2 of length b (the sides)
    # The diagonals should be sqrt(a^2 + b^2)

    if len(set(dists)) != 3:
        return False

    # Diagonals are the 2 largest distances
    diagonal = dists[-1]

    # Check if there are exactly 2 pairs of equal distances among the smallest 4
    from collections import Counter
    counts = Counter(dists[:4])

    # We should have exactly 2 pairs
    if counts.most_common(1)[0][1] != 2:
        return False

    # Check if the pairs have equal count
    if len(set(counts.values())) != 1:
        return False

    # Find the side lengths
    side1, side2 = None, None
    for d, cnt in counts.items():
        if cnt == 2:
            if side1 is None:
                side1 = d
            else:
                side2 = d

    # Check if the diagonal matches Pythagorean theorem
    return abs(diagonal - math.sqrt(side1**2 + side2**2)) < 1e-9

# Read input
points = []
for i in range(8):
    x, y = map(int, input().split())
    points.append((x, y))

# Try all combinations of 4 points to see if they form a square
for square_indices in combinations(range(8), 4):
    square_points = [points[i] for i in square_indices]
    if is_square(square_points):
        rectangle_indices = [i for i in range(8) if i not in square_indices]
        rectangle_points = [points[i] for i in rectangle_indices]

        # Check if the remaining points form a rectangle
        if is_rectangle(rectangle_points):
            print("YES")
            print(" ".join(map(str, square_indices)))
            print(" ".join(map(str, rectangle_indices)))
            break
else:
    print("NO")
