def is_spruce(matrix, n, m, i, j, k):
    """Check if there's a spruce of height k at origin (i, j)"""
    # Check if we can fit a spruce of height k at (i, j)
    # The spruce occupies rows i to i+k-1
    # For row r = i + t, columns range from j-t to j+t
    # Check if all required cells are "*" and no extra cells are "*"
    for t in range(k):
        r = i + t
        start_col = j - t
        end_col = j + t

        # Check if range fits in matrix
        if start_col < 0 or end_col >= m:
            return False

        # Check if all required cells are "*"
        for col in range(start_col, end_col + 1):
            if matrix[r][col] != "*":
                return False

        # Check if no extra cells are "*"
        for col in range(m):
            if col < start_col or col > end_col:
                if matrix[r][col] == "*":
                    return False

    return True

def count_spruces(matrix, n, m):
    """Count all spruces in the matrix"""
    count = 0

    for i in range(n):
        for j in range(m):
            if matrix[i][j] == "*":
                # Check for all possible heights
                for k in range(1, n - i + 1):
                    # Maximum possible height is n - i (since we need k rows)
                    if is_spruce(matrix, n, m, i, j, k):
                        count += 1

    return count

