def solve():
    n, k = map(int, input().split())
    a = list(map(int, input().split()))

    if k == 1:
        print(sum(a))
        return

    positives = [x for x in a if x > 0]
    non_positives = [x for x in a if x <= 0]

    # Put each non-positive element in its own subarray (first k-1 subarrays)
    # Put positives in the last subarray
    subarray_map = [[] for _ in range(k)]

    for i, num in enumerate(non_positives):
        if i < k - 1:
            subarray_map[i].append(num)
        else:
            subarray_map[k - 1].append(num)

    for num in positives:
        subarray_map[k - 1].append(num)

    cost = 0
    for subarray_idx, subarray in enumerate(subarray_map):
        multiplier = subarray_idx + 1
        cost += sum(subarray) * multiplier

    print(cost)

solve()
"}

