        divisors = list(map(int, input().split()))

        # Sort divisors
        divisors.sort()

        # Check if smallest divisor is 2
        if divisors[0] != 2:
            print(-1)
            continue

        # Calculate product
        product = 1
        for d in divisors:
            product *= d

        # Calculate candidate x
        x = 1
        if n % 2 == 0:
            # x = product^(2/n)
            x = product ** (2 / n)
        else:
            # x = product^(2/n) where product = x^(n/2)
            # For odd n, x = product^2
            x = product ** 2

        # Check if x is integer
        if not isinstance(x, int):
            print(-1)
            continue

        # Check if all divisors divide x
        for d in divisors:
            if x % d != 0:
                print(-1)
                break
        else:
            # Check if the number of divisors matches
            # Count divisors of x
            count = 1
            for i in range(2, x + 1):
                if x % i == 0:
                    count += 1

            # The list should have n divisors, and we should have counted all except 1 and x
            if count != n + 2:
                print(-1)
            else:
                print(x)

solve()
