import sys
from collections import defaultdict, deque

def solve() -> None:
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)

    n = int(next(it))
    m = int(next(it))
    T = int(next(it))

    # Build adjacency list
    adj = defaultdict(list)
    for _ in range(m):
        u = int(next(it))
        v = int(next(it))
        t = int(next(it))
        adj[u].append((v, t))

    # Topological sort using Kahn's algorithm
    indegree = [0] * (n + 1)
    for u in adj:
        for v, _ in adj[u]:
            indegree[v] += 1

    q = deque()
    for i in range(1, n + 1):
        if indegree[i] == 0:
            q.append(i)

    topo_order = []
    while q:
        u = q.popleft()
        topo_order.append(u)
        for v, _ in adj[u]:
            indegree[v] -= 1
            if indegree[v] == 0:
                q.append(v)

    # DP: dp[v][k] = minimum time to reach node v with k nodes visited
    INF = float('inf')
    dp = [[INF] * (n + 1) for _ in range(n + 1)]
    dp[1][1] = 0  # start at node 1 with 1 node visited and 0 time

    # For each node in topological order
    for u in topo_order:
        for v, t in adj[u]:
            for k in range(1, n + 1):
                if dp[u][k] + t < dp[v][k + 1]:
                    dp[v][k + 1] = dp[u][k] + t

    # Find maximum k such that dp[n][k] <= T
    max_k = 1
    for k in range(2, n + 1):
        if dp[n][k] <= T:
            max_k = k

    # Reconstruct path
    path = []
    v = n
    for k in range(max_k, 0, -1):
        path.append(v)
        found = False
        for u, t in adj.items():
            for prev, t in zip(adj[u], t):
                if dp[v][k] == dp[u][k - 1] + t:
                    v = u
                    found = True
                    break
            if found:
                break

    path.reverse()

    print(len(path))
    print(' '.join(map(str, path)))

if __name__ == "__main__":
    solve()
