import sys

def determine_category(percentile):
    """Determine category based on percentile rank"""
    if percentile < 50:
        return "noob"
    elif 50 <= percentile < 80:
        return "random"
    elif 80 <= percentile < 90:
        return "average"
    elif 90 <= percentile < 99:
        return "hardcore"
    else:  # >= 99%
        return "pro"

def main():
    data = sys.stdin.read().strip().split('\n')
    if not data:
        return

    n = int(data[0])

    # Track each player's best result
    player_results = {}

    for i in range(1, n + 1):
        name, points = data[i].split()
        points = int(points)
        if name not in player_results or points > player_results[name]:
            player_results[name] = points

    # Create list of (best_result, player_name)
    players = [(points, name) for name, points in player_results.items()]
    players.sort()  # Sort by best result

    m = len(players)
    print(m)

    # Determine category for each player
    for i, (points, name) in enumerate(players):
        # Percentile rank: (number of players with <= points) / total players * 100
        percentile = ((i + 1) / m) * 100
        category = determine_category(percentile)
        print(f"{name} {category}")

if __name__ == "__main__":
    main()
"}

