import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
    t = int(next(it))
    out_lines = []

    for _ in range(t):
        n = int(next(it))
        k = int(next(it))
        x = [int(next(it)) for _ in range(k)]

        # Find the minimum j
        j = 1

        while True:
            covered = set()
            for xi in x:
                left = max(1, xi - (j - 1))  # j-1 steps from tap
                right = min(n, xi + (j - 1))  # j-1 steps from tap
                for pos in range(left, right + 1):
                    covered.add(pos)

            if len(covered) == n:
                out_lines.append(str(j))
                break

            j += 1

    sys.stdout.write("\n".join(out_lines))

if __name__ == "__main__":
    solve()
