def is_convex(grid):
    n = len(grid)
    m = len(grid[0])

    # Find all black cells
    black_cells = [(i, j) for i in range(n) for j in range(m) if grid[i][j] == 'B']

    # Check if all cells in the rectangle between any two black cells are black
    for i1, j1 in black_cells:
        for i2, j2 in black_cells:
            # Get the rectangle from (i1,j1) to (i2,j2)
            min_i = min(i1, i2)
            max_i = max(i1, i2)
            min_j = min(j1, j2)
            max_j = max(j1, j2)

            # Check all cells in this rectangle
            for i in range(min_i, max_i + 1):
                for j in range(min_j, max_j + 1):
                    if grid[i][j] != 'B':
                        return False
    return True

