def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    a = int(data[1])
    checkpoints = list(map(int, data[2:2+n]))

    if n == 1:
        print(0)
        return

    checkpoints.sort()

    if n == 2:
        print(min(abs(a - checkpoints[0]), abs(a - checkpoints[1])))
        return

    # For n > 2, we need to visit n-1 checkpoints
    # We can start at a, go to one end, and then visit all others in that direction
    # Or we can skip a checkpoint in the middle

    min_distance = float('inf')

    # Strategy 1: Start at a, go to checkpoints[0], then visit checkpoints[1..n-1]
    dist1 = abs(a - checkpoints[0])
    for i in range(1, n):
        dist1 += checkpoints[i] - checkpoints[i-1]

    # Strategy 2: Start at a, go to checkpoints[n-1], then visit checkpoints[0..n-2]
    dist2 = abs(a - checkpoints[n-1])
    for i in range(n-2, -1, -1):
        dist2 += checkpoints[i+1] - checkpoints[i]

    # Strategy 3: Skip one checkpoint in the middle and visit all others
    for i in range(n):
        # Skip checkpoints[i]
        # Case 1: Skip leftmost
        if i == 0:
            dist = abs(a - checkpoints[1])
            for j in range(1, n-1):
                dist += checkpoints[j+1] - checkpoints[j]
        elif i == n-1:
            dist = abs(a - checkpoints[n-2])
            for j in range(n-2):
                dist += checkpoints[j+1] - checkpoints[j]
        else:
            # Left block: checkpoints[1..i-1]
            dist = abs(a - checkpoints[1])
            for j in range(1, i):
                dist += checkpoints[j+1] - checkpoints[j]
            # Right block: checkpoints[i+1..n-2]
            for j in range(i+1, n-1):
                dist += checkpoints[j+1] - checkpoints[j]

        min_distance = min(min_distance, dist)

    print(min(min_distance, dist1, dist2))

if __name__ == "__main__":
    solve()
