def combination(n, k):
    if k > n or k < 0:
        return 0
    if k == 0 or k == n:
        return 1
    if k > n - k:
        k = n - k
    result = 1
    for i in range(1, k + 1):
        result = result * (n - i + 1) // i
    return result

def solve():
    n, m, h = map(int, input().split())
    s = list(map(int, input().split()))

    total_players = sum(s)
    if total_players < n:
        print(-1)
        return

    wafa_department_players = s[h - 1]
    other_players = total_players - 1
    other_departments_players = other_players - (wafa_department_players - 1)

    total_ways = combination(total_players - 1, n - 1)
    other_ways = combination(other_departments_players, n - 1)

    probability = (total_ways - other_ways) / total_ways

    if probability == 1:
        print("1")
    elif probability == 0:
        print("0")
    else:
        # Format with 10 decimal places and remove trailing zeros
        formatted = f"{probability:.10f}".rstrip('0').rstrip('.')
        print(formatted)

solve()
