def count_inversions(arr):
    """Count the number of inversions in an array using a naive approach"""
    n = len(arr)
    inversions = 0
    for i in range(n):
        for j in range(i + 1, n):
            if arr[i] > arr[j]:
                inversions += 1
    return inversions

