    k = 2 * q
    if k == 0:
        print(count_inversions(arr))
    else:
        parts = []
        for i in range(0, 2 * n, k):
            part = arr[i:i+k]
            part = part[::-1]
            parts.append(part)
        arr = [num for part in parts for num in part]
        print(count_inversions(arr))
