def solve():
    t = int(input())
    results = []

    for _ in range(t):
        n, k, l = map(int, input().split())
        d = list(map(int, input().split()))

        # Generate p array (length 2k)
        p = []
        for i in range(k):
            p.append(i)
        for i in range(k, 0, -1):
            p.append(i)

        # Check if there's a valid starting time
        found = False
        for shift in range(2 * k):
            # Koa starts at shore at time shift
            # dp[time] = set of positions Koa can be at at time 'time'
            dp = {shift: {0}}

            for time in range(shift + 1, shift + 2 * k + 1):
                dp[time] = set()

                # From previous positions, we can stay or swim
                for pos in dp[time - 1]:
                    # Stay at the same position
                    if pos <= n and d[pos - 1] + p[time % (2 * k)] <= l:
                        dp[time].add(pos)

                    # Swim to position pos + 1 if possible
                    if pos + 1 <= n:
                        # Check if we can swim to pos+1
                        if d[pos] + p[time % (2 * k)] <= l:
                            dp[time].add(pos + 1)

            # Check if we can reach position n
            for time, positions in dp.items():
                if n in positions:
                    # Can reach island from n at time+1
                    found = True
                    break

        results.append("Yes" if found else "No")

    print("\n".join(results))

solve()
