import sys

def solve() -> None:
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    m = int(data[1])

    # Build adjacency list
    adj = [[] for _ in range(n + 1)]

    for i in range(m):
        j = int(data[2 + 2 * i])
        k = int(data[3 + 2 * i])
        adj[j].append(k)

    # Cycle detection using DFS
    visited = [False] * (n + 1)
    recursion_stack = set()
    has_cycle = False

    def dfs(node):
        nonlocal has_cycle
        if visited[node]:
            return

        visited[node] = True
        recursion_stack.add(node)

        for neighbor in adj[node]:
            dfs(neighbor)

        recursion_stack.remove(node)

        if node in recursion_stack:
            has_cycle = True

    for i in range(1, n + 1):
        dfs(i)

    if has_cycle:
        sys.stdout.write('-1\n')
        return

    # Assign A to nodes with in-degree 0
    in_degree = [0] * (n + 1)
    for j in range(1, n + 1):
        for k in adj[j]:
            in_degree[k] += 1

    result = ['E'] * n

    queue = [i for i in range(1, n + 1) if in_degree[i] == 0]

    while queue:
        u = queue.pop(0)
        result[u - 1] = 'A'

        for v in adj[u]:
            in_degree[v] -= 1
            if in_degree[v] == 0:
                queue.append(v)

    sys.stdout.write(str(result.count('A')) + '\n')
    sys.stdout.write(''.join(result) + '\n')

if __name__ == '__main__':
    solve()
