import heapq

def dijkstra(n, adj, s):
    """Compute shortest paths from s to all nodes using Dijkstra's algorithm."""
    dist = [float('inf')] * (n + 1)
    dist[s] = 0
    heap = [(0, s)]

    while heap:
        d, u = heapq.heappop(heap)
        if d > dist[u]:
            continue
        for v, w in adj[u]:
            if dist[v] > dist[u] + w:
                dist[v] = dist[u] + w
                heapq.heappush(heap, (dist[v], v))
    return dist

n, m, s, t = map(int, input().split())

# Build adjacency list
adj = [[] for _ in range(n + 1)]
roads = []
for _ in range(m):
    a, b, l = map(int, input().split())
    adj[a].append((b, l))
    roads.append((a, b, l))

# Compute shortest paths from s to all nodes
dist_s = dijkstra(n, adj, s)

# Compute shortest paths from t to all nodes (distances from all nodes to t)
dist_t = [float('inf')] * (n + 1)
dist_t[t] = 0
heap = [(0, t)]

while heap:
    d, u = heapq.heappop(heap)
    if d > dist_t[u]:
        continue
    for v, w in adj[u]:
        if dist_t[v] > dist_t[u] + w:
            dist_t[v] = dist_t[u] + w
            heapq.heappush(heap, (dist_t[v], v))

# Process each road
for a, b, l in roads:
