import sys
from collections import defaultdict, deque

def solve() -> None:
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
    n = int(next(it))
    m = int(next(it))
    T = int(next(it))

    # Build adjacency list
    graph = defaultdict(list)
    for _ in range(m):
        u = int(next(it))
        v = int(next(it))
        w = int(next(it))
        graph[u].append((v, w))

    # Topological sort using Kahn's algorithm
    in_degree = [0] * (n + 1)
    for u in graph:
        for v, _ in graph[u]:
            in_degree[v] += 1

    queue = deque()
    for i in range(1, n + 1):
        if in_degree[i] == 0:
            queue.append(i)

    topo_order = []
    while queue:
        u = queue.popleft()
        topo_order.append(u)
        for v, _ in graph[u]:
            in_degree[v] -= 1
            if in_degree[v] == 0:
                queue.append(v)

    # DP: dp[u] is a dictionary mapping time to (max_nodes, path)
    # Initially, we're at node 1 with 0 time and 1 node
    dp = [defaultdict(lambda: (0, [])) for _ in range(n + 1)]
    dp[1][0] = (1, [1])

    for u in topo_order:
        if not dp[u]:
            continue

        for time, (nodes, path) in dp[u].items():
            if time > T:
                continue

            for v, weight in graph[u]:
                new_time = time + weight
                if new_time > T:
                    continue

                new_nodes = nodes + 1
                new_path = path + [v]

                # Update dp[v]
                current = dp[v].get(new_time, (0, []))
                if new_nodes > current[0]:
                    dp[v][new_time] = (new_nodes, new_path)

    # Find the maximum number of nodes in dp[n]
    max_nodes = 0
    best_path = []
    for time, (nodes, path) in dp[n].items():
        if nodes > max_nodes:
            max_nodes = nodes
            best_path = path

    print(max_nodes)
    print(' '.join(map(str, best_path)))

if __name__ == "__main__":
    solve()
