import sys
from collections import defaultdict, deque

def solve() -> None:
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
    n = int(next(it))
    m = int(next(it))
    T = int(next(it))

    # Build adjacency list
    graph = defaultdict(list)
    for _ in range(m):
        u = int(next(it))
        v = int(next(it))
        w = int(next(it))
        graph[u].append((v, w))

    # Topological sort using Kahn's algorithm
    in_degree = [0] * (n + 1)
    for u in graph:
        for v, _ in graph[u]:
            in_degree[v] += 1

    queue = deque()
    for i in range(1, n + 1):
        if in_degree[i] == 0:
            queue.append(i)

    topo_order = []
    while queue:
        u = queue.popleft()
        topo_order.append(u)
        for v, _ in graph[u]:
            in_degree[v] -= 1
            if in_degree[v] == 0:
                queue.append(v)

    # DP: dp[u] is a dictionary mapping time to max number of nodes
    # Initially, we're at node 1 with 0 time and 1 node
    dp = [defaultdict(int) for _ in range(n + 1)]
    dp[1][0] = 1

    for u in topo_order:
        if not dp[u]:
            continue

        for time, nodes in dp[u].items():
            if time > T:
                continue

            for v, weight in graph[u]:
                new_time = time + weight
                if new_time > T:
                    continue

                new_nodes = nodes + 1

                # Update dp[v]
                if new_nodes > dp[v][new_time]:
                    dp[v][new_time] = new_nodes

