import sys

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    n = int(data[0])
    m = int(data[1])
    a = list(map(int, data[2:2+n]))

    # dp[i] = minimum distance to catch first i criminals
    dp = [0] * (n + 1)

    for i in range(1, n + 1):
        # Try all possible previous partitions
        for j in range(max(0, i - m), i):
            dp[i] = min(dp[i], dp[j] + 2 * (a[i-1] - a[j]))

    print(dp[n])

if __name__ == "__main__":
    main()
