def is_spruce(matrix, n, m, x, y, k):
    """Check if there's a spruce of height k with origin at (x, y)"""
    # Check if all required cells are '*' and no others are included
    for i in range(1, k + 1):
        # Row x+i-1 should have columns [y-i+1, y+i-1]
        row = x + i - 1
        left = y - i + 1
        right = y + i - 1

        # Check if this row is within bounds
        if row >= n or left < 0 or right >= m:
            return False

        # Check all cells in this row's range are '*'
        for col in range(left, right + 1):
            if matrix[row][col] != '*':
                return False

        # Check cells outside this range are not part of the spruce
        # They should all be '.'
        for col in range(0, m):
            if col < left or col > right:
