def find_mst_weight(n, p, a):

    # Adjacent vertices always have an edge of weight p
    edges = []
    for i in range(1, n):
        edges.append((p, i, i + 1))

    # For non-adjacent vertices, we need to check if min divides all elements in the subarray
    # We'll use a sliding window approach

    # For each possible min value, find ranges where it is the minimum
    # and divides all elements

    # Since a[i] can be up to 1e9, we need a smarter way

    # For each index, find the range where a[i] is the min
    # and a[i] divides all elements in that range
    for i in range(n):
        # Find the range where a[i] is the minimum
        left, right = i, i
        # Expand to the left
        while left > 0 and a[left - 1] >= a[i]:
            left -= 1
        # Expand to the right
        while right < n - 1 and a[right + 1] >= a[i]:
            right += 1

        # Check if a[i] divides all elements in this range
        valid = True
        for j in range(left, right + 1):
            if a[j] % a[i] != 0:
                valid = False
                break

        if valid:
            # Add edges between vertices in this range
            for k in range(left, right + 1):
                if k > i:
                    edges.append((a[i], (i + 1), (k + 1)))

    # Sort edges by weight
    edges.sort()

    # Kruskal's algorithm
    parent = list(range(n + 1))

    def find(x):
        if parent[x] != x:
            parent[x] = find(parent[x])
        return parent[x]

    def union(x, y):
        px, py = find(x), find(y)
        if px != py:
            parent[py] = px
            return True
        return False

    total = 0
    count = 0
    for weight, u, v in edges:
        if union(u, v):
            total += weight
            count += 1
            if count == n - 1:
                break

    return total


