K = 3
center = (K + 1) // 2

# Track which seats are occupied (1 means occupied)
occupied = [[0] * K for _ in range(K)]

# For each request
requests = [1, 2, 3, 1]

for i, m in enumerate(requests, 1):
    best_value = float('inf')
    best_row = -1
    best_start = -1
    best_end = -1

    for row in range(K):
        # Check all possible segments of length m in this row
        for start in range(K - m + 1):
            end = start + m - 1

            # Check if all seats in this segment are free
            all_free = True
            for seat in range(start, end + 1):
                if occupied[row][seat]:
                    all_free = False
                    break

            if all_free:
                # Calculate remoteness
                remoteness = abs(row + 1 - center) + sum(abs(seat + 1 - center) for seat in range(start, end + 1))

                # Choose the best segment
                if remoteness < best_value:
                    best_value = remoteness
                    best_row = row + 1  # Rows are 1-indexed
                    best_start = start + 1  # Seats are 1-indexed
                    best_end = end + 1
                elif remoteness == best_value:
                    # If tie, prefer lower row
                    if row + 1 < best_row:
                        best_row = row + 1
                        best_start = start + 1
                        best_end = end + 1
                    elif row + 1 == best_row:
                        # If row is same, prefer lower start
                        if start + 1 < best_start:
                            best_start = start + 1
                            best_end = end + 1

    if best_row == -1:
        print(f"-1")
    else:
        print(f"{best_row} {best_start} {best_end}")

    # Mark the chosen seats as occupied (if found)
    if best_row != -1:
        for seat in range(best_start - 1, best_end):
            occupied[best_row - 1][seat] = 1
