def find_possible_suffixes(s):
    n = len(s)
    possible_suffixes = set()

    # For each possible root length (≥ 5)
    for root_len in range(5, n + 1):
        suffix_len = n - root_len
        suffix_part = s[root_len:]  # Characters from root to end

        # We need to find all suffixes of length 2 or 3 that could be at the end
        # We can have sequences of 2-length and 3-length suffixes
        # Let's find all suffixes of length 2 or 3 that appear in the suffix part
        for i in range(len(suffix_part) - 1):
            if i + 2 <= len(suffix_part):
                suffix2 = suffix_part[i:i+2]
                possible_suffixes.add(suffix2)
            if i + 3 <= len(suffix_part):
                suffix3 = suffix_part[i:i+3]
                possible_suffixes.add(suffix3)

