import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    points = list(map(int, data[1:1+n]))

    # Check each pair of consecutive semi-circles
    for i in range(n - 1):
        for j in range(i + 1, n - 1):
            # Semi-circle i: between points[i] and points[i+1]
            a, b = points[i], points[i+1]
            # Make intervals (min, max)
            if a > b:
                a, b = b, a

            # Semi-circle j: between points[j] and points[j+1]
            c, d = points[j], points[j+1]
            # Make intervals (min, max)
            if c > d:
                c, d = d, c

            # Check if intervals overlap but are not nested
            # Overlap condition: max(a, c) < min(b, d)
            # Non-nesting condition: NOT ((a < c and b > d) or (c < a and d > b))
            if max(a, c) < min(b, d):
                # Check if they are not nested
                if not ((a < c and b > d) or (c < a and d > b)):
                    print("yes")
                    return

    print("no")

if __name__ == "__main__":
    solve()
