import math

A, B, C = map(int, input().split())

if A == 0 and B == 0 and C == 0:
    print(-1)
elif A == 0 and B == 0:
    print(0)
elif A == 0:
    # Linear equation: Bx + C = 0
    root = -C / B
    # Print as "0.000000" for positive zero
    if root == 0:
        print("0.000000")
    else:
        print(f"{root:.6f}")
else:
    # Quadratic equation: Ax² + Bx + C = 0
    discriminant = B * B - 4 * A * C

    if discriminant < 0:
        print(0)
    elif discriminant == 0:
        root = -B / (2 * A)
        print(1)
        print(f"{root:.6f}")
    else:
        sqrt_d = math.sqrt(discriminant)
        root1 = (-B - sqrt_d) / (2 * A)
        root2 = (-B + sqrt_d) / (2 * A)

        # Sort roots
        if root1 > root2:
            root1, root2 = root2, root1

        print(2)
        print(f"{root1:.6f}")
        print(f"{root2:.6f}")
"}

