def solve():
    from collections import deque

    # Read input
    r, c = map(int, input().split())
    grid = []
    start_pos = None
    exit_pos = None

    for i in range(r):
        row = input().strip()
        grid.append(row)

        for j, ch in enumerate(row):
            if ch == 'S':
                start_pos = (i, j)
            elif ch == 'E':
                exit_pos = (i, j)

    # BFS from start to find shortest path to exit
    distances = [[-1] * c for _ in range(r)]
    dq = deque([start_pos])
    distances[start_pos[0]][start_pos[1]] = 0

    while dq:
        i, j = dq.popleft()

        for di, dj in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            ni, nj = i + di, j + dj
            if 0 <= ni < r and 0 <= nj < c:
                if distances[ni][nj] == -1 and grid[ni][nj] != 'T':
                    distances[ni][nj] = distances[i][j] + 1
                    dq.append((ni, nj))

    # Count breeders that can reach exit in exactly the same number of moves
    result = 0
    for i in range(r):
        for j in range(c):
            if grid[i][j] != 'T' and distances[i][j] != -1:
                # Breeder count at this cell
                breeder_count = int(grid[i][j]) if grid[i][j].isdigit() else 0
                if distances[i][j] == distances[exit_pos[0]][exit_pos[1]] and i == exit_pos[0] and j == exit_pos[1]:
                    result += breeder_count

    print(result)

solve()
