    distances_from_start[start_pos[0]][start_pos[1]] = 0

    while dq:
        i, j = dq.popleft()

        for di, dj in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            ni, nj = i + di, j + dj
            if 0 <= ni < r and 0 <= nj < c:
                if distances_from_start[ni][nj] == -1 and grid[ni][nj] != 'T':
                    distances_from_start[ni][nj] = distances_from_start[i][j] + 1
                    dq.append((ni, nj))

    # BFS from exit to find shortest path from each cell to exit
    distances_from_exit = [[-1] * c for _ in range(r)]
    dq = deque([exit_pos])
    distances_from_exit[exit_pos[0]][exit_pos[1]] = 0

    while dq:
        i, j = dq.popleft()

        for di, dj in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            ni, nj = i + di, j + dj
            if 0 <= ni < r and 0 <= nj < c:
                if distances_from_exit[ni][nj] == -1 and grid[ni][nj] != 'T':
                    distances_from_exit[ni][nj] = distances_from_exit[i][j] + 1
                    dq.append((ni, nj))

    # Find shortest path from start to exit
    k = distances_from_start[exit_pos[0]][exit_pos[1]]

    # Count breeders that can reach exit in at most k moves
    result = 0

    for i in range(r):
        for j in range(c):
            if grid[i][j] != 'T' and distances_from_start[i][j] != -1:
                # Breeder count at this cell
                breeder_count = int(grid[i][j]) if grid[i][j].isdigit() else 0
                if distances_from_exit[i][j] <= k:
                    result += breeder_count

    print(result)

