import sys

def solve() -> None:
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    colors = list(map(int, data[1:1+n]))

    # Find first occurrence of each color (1-indexed)
    first = {}
    for idx in range(n):
        color = colors[idx]
        if color not in first:
            first[color] = idx + 1  # 1-indexed

    # Find last occurrence of each color (1-indexed)
    last = {}
    for idx in range(n):
        color = colors[idx]
        last[color] = idx + 1  # 1-indexed

    max_dist = 0

    # For each color, check distance to houses of different colors
    for color in first:
        # Distance to the furthest house of a different color
        # Could be the last occurrence of another color
        for other_color in last:
            if other_color != color:
                dist = abs(last[other_color] - first[color])
                max_dist = max(max_dist, dist)

    print(max_dist)

if __name__ == "__main__":
    solve()
"}

